int main(int argc,char**argv){int n=atoi(argv[1]),steps=atoi(argv[2]),full=(1<<n)-1;int *idx=malloc((full+1)*4),*rep=malloc((full+1)*4),*mem=malloc((full+1)*4),*off=malloc((full+1)*4),*sz=malloc((full+1)*4),N=0,M=0;for(int i=0;i<=full;i++)idx[i]=-1;for(int x=0;x<=full;x++){if((x&(x<<1))||((x&1)&&(x&(1<<(n-1))))||idx[x]>=0)continue;rep[N]=x;off[N]=M;int y=0;for(int i=0;i<n;i++)if(x>>i&1)y|=1<<(n-1-i);int z=x;for(int i=0;i<n;i++){if(idx[z]<0){idx[z]=N;mem[M++]=z;}if(idx[y]<0){idx[y]=N;mem[M++]=y;}z=((z<<1)&full)|(z>>(n-1));y=((y<<1)&full)|(y>>(n-1));}sz[N]=M-off[N];N++;}free(idx);unsigned char*A=calloc(N*N,1);for(int i=0;i<N;i++)for(int j=0;j<N;j++)for(int k=0;k<sz[j];k++)if(!(rep[i]&mem[off[j]+k]))A[i*N+j]++;ll*v=calloc(N,8),*w=calloc(N,8),*s=calloc(steps+1,8);v[0]=1;for(int k=0;k<=steps;k++){ll a=0;for(int i=0;i<N;i++)a=(a+sz[i]*v[i])%p;s[k]=a;for(int i=0;i<N;i++){ll z=0;unsigned char *row=A+i*N;for(int j=0;j<N;j++)z+=row[j]*v[j];z%=p;w[i]=__builtin_popcount((unsigned)rep[i])%2?(p-z)%p:z;}ll*t=v;v=w;w=t;}ll*C=calloc(steps+2,8),*B=calloc(steps+2,8),*T=calloc(steps+2,8);C[0]=B[0]=1;int L=0,m=1,cl=1,bl=1;ll b=1;for(int k=0;k<=steps;k++){ll d=s[k];for(int i=1;i<=L;i++)d=(d+C[i]*s[k-i])%p;if(!d){m++;continue;}memcpy(T,C,(steps+2)*8);int tl=cl;ll c=d*pw(b,p-2)%p;for(int i=0;i<bl;i++)C[i+m]=(C[i+m]-c*B[i]%p+p)%p;if(cl<bl+m)cl=bl+m;if(2*L<=k){L=k+1-L;memcpy(B,T,(steps+2)*8);bl=tl;b=d;m=1;}else m++;}printf("{\"n\":%d,\"steps\":%d,\"prime\":%lld,\"row_states\":%d,\"dihedral_orbits\":%d,\"BM_degree\":%d,\"C\":[",n,steps,p,M,N,L);for(int i=0;i<=L;i++)printf("%s%lld",i?",":"",C[i]);printf("],\"sequence\":[");for(int i=0;i<=steps;i++)printf("%s%lld",i?",":"",s[i]);printf("]}\n");}
